from decimal import Decimal, ROUND_HALF_UP, localcontext


def _value(row: dict, key: str) -> object:
    """Return a row value, treating missing and None values as legacy empty."""
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: object, width: int) -> str:
    """Legacy FIXED: left-align, right-pad, and truncate."""
    text = str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: object, width: int) -> str:
    """Legacy ZPAD after conversion of annual revenue to integer cents."""
    with localcontext() as context:
        context.prec = 64
        cents = (Decimal(str(value)) * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
    return format(cents, "f").rjust(width, "0")


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT record without a record terminator."""
    ann_rev = _value(row, "ANN_REV")
    if ann_rev == "":
        ann_rev = 0

    cred_hold = _value(row, "CRED_HOLD")
    if cred_hold == "":
        cred_hold = "N"

    create_dt = _value(row, "CREATE_DT")
    if create_dt == "":
        create_dt = "00000000"

    return (
        _fixed(_value(row, "ACCT_ID"), 10)
        + _fixed(_value(row, "ACCT_NM"), 40)
        + _fixed(_value(row, "REGION_CD"), 3)
        + _zpad_cents(ann_rev, 15)
        + str(cred_hold)
        + str(create_dt)
    )
